import { test, expect } from "@playwright/test";
import { AxeBuilder } from "@axe-core/playwright";

// Generated by Run Hound (axe-states). Fails while the problem is present.
const TARGET = "http://localhost:3160/book";

test("no \"button-name\" violations in the initial state", async ({ page }) => {
  await page.goto(TARGET, { waitUntil: "networkidle" });
  // Let entrance animations end first, so text is not measured while it fades in.
  await page.evaluate(() => Promise.race([
    Promise.all(document.getAnimations().filter((a) => Number.isFinite(a.effect?.getComputedTiming().endTime)).map((a) => a.finished.catch(() => undefined))),
    new Promise((resolve) => setTimeout(resolve, 3000)),
  ]));
  const results = await new AxeBuilder({ page }).withTags(["wcag2a","wcag2aa","wcag21a","wcag21aa","wcag22aa"]).withRules("button-name").analyze();
  expect(results.violations).toEqual([]);
});

