const TARGET = "http://localhost:3160/book";

test("clicking \"Save draft\" does something", async ({ page }) => {
  await page.goto(TARGET);
  await page.getByLabel("Pet name", { exact: true }).fill("name 6d779656dead");
  await page.getByText("Dog", { exact: true }).first().click(); // Pet type
  await page.getByLabel("Start date", { exact: true }).fill("2026-10-11");
  await page.getByLabel("End date", { exact: true }).fill("2026-10-14");
  await page.getByLabel("Owner email", { exact: true }).fill("owner.6d779656dead@example.test");
  await page.getByPlaceholder("Phone", { exact: true }).or(page.getByLabel("Phone", { exact: true })).first().fill("+1 555 0167 915");
  await page.getByLabel("Special instructions", { exact: true }).fill("Feed twice a day, note 6d779656dead");
  await page.getByLabel("Password", { exact: true }).fill("Fake-Passw0rd-6d779656dead!");
  await page.getByLabel("Confirm password", { exact: true }).fill("Fake-Passw0rd-6d779656dead!");
  // The same reactions Run Hound looks for: DOM, storage, URL, field values, a request, or focus moving elsewhere.
  const snapshot = () =>
    page.evaluate(() =>
      JSON.stringify([
        document.body.innerHTML,
        { ...localStorage },
        { ...sessionStorage },
        location.href,
        [...document.querySelectorAll("input, select, textarea")].map((e) => { const i = e as HTMLInputElement; return i.type === "checkbox" || i.type === "radio" ? i.checked : i.value; }),
      ]),
    );
  {
    const control = page.getByRole("button", { name: "Save draft", exact: true });
    // Let the page finish loading first, so its own loading isn't mistaken for the click's effect.
    await page.waitForLoadState("networkidle");
    await control.waitFor();
    const requests: string[] = [];
    page.on("request", (r) => requests.push(r.url()));
    const before = await snapshot();
    await page.evaluate(() => { (window as unknown as { focusBefore: Element | null }).focusBefore = document.activeElement; });
    await control.click();
    await page.waitForTimeout(1500);
    const after = await snapshot();
    const focusMoved = await control.evaluate((c) => { const a = document.activeElement; return !!a && a !== c && a !== document.body && a !== (window as unknown as { focusBefore: Element | null }).focusBefore; });
    expect(after !== before || requests.length > 0 || focusMoved, "\"Save draft\" should change something").toBe(true);
  }
});

