// Generated by Run Hound (pii-leak). Fails while the problem is present.
const TARGET = "http://localhost:3160/book";

test("email address is not sent to localhost:3161", async ({ page }) => {
  await page.goto(TARGET, { waitUntil: "networkidle" });
  // Any request to another origin than the app (not only localhost:3161) must not carry the value.
  const backends: string[] = [];
  const leaks: string[] = [];
  const decode = (text: string) => {
    try {
      return decodeURIComponent(text);
    } catch {
      return text;
    }
  };
  page.on("request", (req) => {
    const text = req.url() + " " + decode(req.url()) + " " + (req.postData() ?? "");
    const origin = new URL(req.url()).origin;
    if (origin !== new URL(TARGET).origin && !backends.includes(origin) && text.includes("runhound-6d779656@example.com")) leaks.push(req.url());
  });
  await page.getByLabel("Pet name", { exact: true }).fill("Rh 6d779656");
  await page.getByText("Dog", { exact: true }).first().click(); // Pet type
  await page.getByLabel("Start date", { exact: true }).fill("2026-10-27");
  await page.getByLabel("End date", { exact: true }).fill("2026-10-30");
  await page.getByLabel("Owner email", { exact: true }).fill("runhound-6d779656@example.com");
  await page.getByPlaceholder("Phone", { exact: true }).or(page.getByLabel("Phone", { exact: true })).first().fill("5556748419");
  await page.getByLabel("Special instructions", { exact: true }).fill("Run Hound test 6d779656");
  await page.getByRole("button", { name: "Book", exact: true }).click();
  await page.waitForLoadState("networkidle");
  await page.waitForTimeout(1500);
  expect(leaks).toEqual([]);
});

